<?php
namespace App\Http\Controllers;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;
final class AuthController extends Controller {public function create(){if(Auth::check())return redirect()->route('chat.index');return view('auth.login');}public function store(Request $request){$credentials=$request->validate(['email'=>'required|email','password'=>'required|string']);if(!Auth::attempt($credentials,$request->boolean('remember'))){return back()->withErrors(['email'=>__('ui.auth_failed')])->onlyInput('email');}$request->session()->regenerate();return redirect()->intended(route('chat.index'));}public function destroy(Request $request){Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();return redirect()->route('login');}}
